function slugify(value) {
  return String(value || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function decode(value) {
  return String(value || "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&amp;/gi, "&").replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim();
}

function meta(html, property) {
  const escaped = property.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const patterns = [
    new RegExp(`<meta[^>]+(?:property|name)=["']${escaped}["'][^>]+content=["']([^"']+)["']`, "i"),
    new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${escaped}["']`, "i"),
  ];
  return decode(patterns.map((pattern) => html.match(pattern)?.[1]).find(Boolean));
}

function absoluteUrl(value, base) {
  try { return value ? new URL(value, base).href : ""; } catch { return ""; }
}

function isTrusted(url) {
  try {
    const host = new URL(url).hostname;
    return trustedHosts.some((pattern) => pattern.test(host));
  } catch { return false; }
}

function sourceLabel(place, finalUrl) {
  const host = new URL(finalUrl).hostname.replace(/^www\./, "");
  if (host === "ncparks.gov" || host.endsWith(".ncparks.gov")) return "North Carolina State Parks";
  return place.sourceLabel === "Official website" ? "Official park website" : place.sourceLabel;
}

function answer(intentKey, question, text, label, source) {
  return { intentKey, question, answer: text, sourceLabel: label, source, sourceType: "official", checkedAt };
}

function overrideFor(overrides, place, name) {
  const rawId = String(place.id || "");
  const normalizedId = rawId.replace(/^basic-/, "");
  return overrides[rawId] ?? overrides[normalizedId] ?? overrides[`${place.city}:${name}`] ?? overrides[name];
}

async function research(place) {
  const lookupName = place.legacyName || place.name;
  const details = overrideFor(detailOverrides, place, lookupName) || {};
  const displayName = details.canonicalName || place.name;
  const city = details.city || place.city;
  const address = details.address || place.address;
  const researchUrl = overrideFor(sourceOverrides, place, lookupName) || place.source;
  let response;
  let finalUrl = researchUrl;
  let html = "";
  try {
    response = await fetch(researchUrl, {
      redirect: "follow",
      headers: { "User-Agent": "AuditMap/1.0 (https://www.auditmap.org)", "Accept-Language": "en-US,en" },
      signal: AbortSignal.timeout(20000),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    finalUrl = response.url;
    html = await response.text();
  } catch (error) {
    // Some municipal directories block automated fetches even when their indexed
    // records and direct assets are public. Curated overrides still let us publish
    // the verified text layer while deferring the image rather than losing the park.
    if (!overrideFor(detailOverrides, place, lookupName)) throw error;
  }
  if (!isTrusted(finalUrl)) throw new Error(`untrusted redirect: ${new URL(finalUrl).hostname}`);
  const description = meta(html, "description") || meta(html, "og:description");
  const imageCandidate = overrideFor(officialImageOverrides, place, lookupName) || (invalidImageNames.has(lookupName)
    ? ""
    : absoluteUrl(meta(html, "og:image") || meta(html, "twitter:image"), finalUrl));
  const imageUrl = (/^https:\/\//i.test(imageCandidate) || imageCandidate.startsWith("/assets/")) && !/\b(logo|seal|icon)\b/i.test(imageCandidate)
    ? imageCandidate
    : "";
  const label = sourceLabel(place, finalUrl);
  const imageMetadata = overrideFor(officialImageMetadataOverrides, place, lookupName) || {};
  const hoursValue = details.hours || place.hours;
  const hoursKnown = hoursValue && !/not yet documented/i.test(hoursValue);
  const amenities = details.amenities || (place.amenities?.length ? place.amenities : []);
  const summary = details.summary || (description && description.length > 45
    ? description.slice(0, 500)
    : `${place.name} is a publicly documented park in ${place.city}. This Basic record confirms its location and official visitor-information source while additional amenity details are being catalogued.`);
  const hoursText = hoursKnown
    ? `${hoursValue} Check the official park page for holiday, weather, seasonal, or maintenance changes.`
    : `The operator does not publish dependable hours in the mapped record. Check the official park page and entrance signs before an early or late visit.`;
  const amenitiesText = amenities.length
    ? `Public records currently identify ${amenities.join(", ")}. Check the official page for current availability.`
    : `The official park page is the current source for facilities and closures. AuditMap has not yet independently catalogued every amenity at this Basic-tier listing.`;
  const record = {
    ...place,
    id: place.id.startsWith("basic-") ? place.id : `basic-${place.id}`,
    name: displayName,
    slug: slugify(displayName),
    city,
    address,
    legacyName: displayName !== lookupName ? lookupName : place.legacyName,
    alternateNames: displayName !== lookupName
      ? [...new Set([lookupName, ...(place.alternateNames || [])])]
      : place.alternateNames,
    citySlug: `${slugify(city)}-nc`,
    searchCategory: "park",
    status: "Open status varies",
    hours: hoursValue,
    amenities,
    cost: details.cost || place.cost,
    accessibility: details.accessibility || place.accessibility,
    source: finalUrl,
    sourceLabel: label,
    verifiedAt: checkedAt,
    enrichmentTier: "basic",
    publishStatus: imageUrl ? "enriched-basic" : "deferred",
    discoveryStatus: undefined,
    summary,
    searchDescription: `Official visitor guide to ${displayName} location, hours, parking, amenities, accessibility, dogs, and current visit planning in ${city}, North Carolina.`,
    image: imageUrl ? {
      url: imageUrl,
      source: imageMetadata.source || finalUrl,
      author: imageMetadata.author || label,
      license: imageMetadata.license || "Official website image; see source",
      alt: imageMetadata.alt || displayName,
    } : undefined,
    images: (overrideFor(officialGalleryOverrides, place, lookupName) || []).map((image) => ({
      ...image,
      source: image.source || finalUrl,
      license: image.license || "Official website image; see source",
    })),
    searchAnswers: [
      answer("location", `Where is ${displayName}?`, `${displayName} is mapped at ${address} in ${city}, North Carolina. Use the map pin for the park itself rather than a similarly named municipal office or neighborhood.`, label, finalUrl),
      answer("hours", `What hours is ${displayName} open?`, hoursText, label, finalUrl),
      answer("parking", `Where should I park for ${displayName}?`, details.parking || `Navigate to the mapped park location at ${address}. Parking layout and overflow rules are not yet fully catalogued in this Basic record, so follow official signs and do not block neighborhood streets or service entrances.`, label, finalUrl),
      answer("amenities", `What can I do at ${displayName}?`, amenitiesText, label, finalUrl),
      answer("accessibility", `What accessibility information is available for ${displayName}?`, /not yet documented/i.test((details.accessibility || place.accessibility) || "") ? `Route-level accessibility is not yet documented in AuditMap. Use the official park page for published accessible facilities and contact the operator for a specific route or accommodation.` : `${details.accessibility || place.accessibility} Confirm route-specific needs with the operator because surfaces and closures can change.`, label, finalUrl),
      answer("dogs", `Are dogs allowed at ${displayName}?`, details.dogPolicy || (place.type === "Dog park" ? `This is mapped as a dog park. Review posted separation, leash, vaccination, and maintenance rules at the entrance before use.` : `Dog rules are not yet independently catalogued for this Basic record. Follow entrance signs and the operator's current leash rules; do not assume off-leash use is allowed.`), label, finalUrl),
    ],
  };
  delete record._sourceTags;
  if (!record.image) delete record.image;
  return record;
}

async function main() {
  const inventory = JSON.parse(fs.readFileSync(inventoryPath, "utf8"));
  const institutions = JSON.parse(fs.readFileSync(institutionsPath, "utf8")).map((place) => {
    const identity = String(place.id || "").replace(/^basic-/, "");
    const reason = excludedPlaceIds.get(identity);
    return reason ? { ...place, publishStatus: "excluded", exclusionReason: reason } : place;
  });
  const discoveredCandidates = inventory.places.filter((place) =>
    place.inventoryStatus === "park-candidate" && (isTrusted(place.source) || overrideFor(sourceOverrides, place, place.name)) &&
    !excludedPlaceIds.has(String(place.id || "").replace(/^basic-/, "")) &&
    !/dog park at dix park/i.test(place.name),
  );
  const existingBasicCandidates = institutions.filter((place) =>
    place.id?.startsWith("basic-") && isTrusted(place.source) &&
    !excludedPlaceIds.has(String(place.id || "").replace(/^basic-/, "")) &&
    !/dog park at dix park/i.test(place.name),
  );
  const candidates = [...discoveredCandidates, ...existingBasicCandidates].filter((place, index, places) => {
    const identity = String(place.id || "").replace(/^basic-/, "");
    return places.findIndex((candidate) => String(candidate.id || "").replace(/^basic-/, "") === identity) === index;
  });
  const promoted = [];
  const failures = [];
  for (let index = 0; index < candidates.length; index += 5) {
    const batch = candidates.slice(index, index + 5);
    const results = await Promise.allSettled(batch.map(research));
    results.forEach((result, offset) => {
      const place = batch[offset];
      if (result.status === "fulfilled") promoted.push(result.value);
      else failures.push({ id: place.id, name: place.name, city: place.city, source: place.source, error: result.reason.message });
    });
    console.log(`Researched ${Math.min(index + 5, candidates.length)}/${candidates.length}`);
  }
  const document = { generatedAt: new Date().toISOString(), candidates: candidates.length, promoted: promoted.length, withImages: promoted.filter((place) => place.image?.url).length, failures, places: promoted };
  fs.writeFileSync(outputPath, `${JSON.stringify(document, null, 2)}\n`);

  const promotedIds = new Set(promoted.map((place) => place.id));
  const next = [...institutions.filter((place) => !promotedIds.has(place.id)), ...promoted];
  fs.writeFileSync(institutionsPath, `${JSON.stringify(next, null, 2)}\n`);

  const promotedByDiscoveryId = new Map(promoted.map((place) => [place.id.replace(/^basic-/, ""), place]));
  const synchronizedPlaces = inventory.places.map((place) => {
    const exclusionReason = excludedPlaceIds.get(String(place.id || "").replace(/^basic-/, ""));
    if (exclusionReason) return { ...place, publishStatus: "excluded", exclusionReason };
    const official = promotedByDiscoveryId.get(place.id);
    if (!official) return place;
    const unresolved = [];
    if (!official.image?.url) unresolved.push("image");
    if (!overrideFor(detailOverrides, place, place.name)?.parking) unresolved.push("parking");
    if (!official.hours || /not yet documented/i.test(official.hours)) unresolved.push("hours");
    if (!official.amenities?.length) unresolved.push("amenities");
    if (!official.accessibility || /not yet documented/i.test(official.accessibility)) unresolved.push("accessibility");
    return {
      ...place,
      ...official,
      id: place.id,
      inventoryStatus: place.inventoryStatus,
      enrichmentTier: "basic",
      completenessScore: Math.max(40, 100 - (unresolved.length * 10)),
      unresolvedIntentKeys: unresolved,
    };
  });
  fs.writeFileSync(inventoryPath, `${JSON.stringify({
    ...inventory,
    officialPromotionSynchronizedAt: new Date().toISOString(),
    places: synchronizedPlaces,
  }, null, 2)}\n`);
  console.log(JSON.stringify({ candidates: candidates.length, promoted: promoted.length, withImages: document.withImages, failures: failures.length, catalogSize: next.length }, null, 2));
}

main().catch((error) => { console.error(error); process.exitCode = 1; });
